const headers = {
  'Content-Type': 'application/json',
};
export const setSubRoot = async (params: any): Promise<string | void> => {
  try {
    const rsp = await fetch('https://cri-test.zplan.qq.com/mini_app/set_sub_root', {
      method: 'POST',
      headers,
      body: JSON.stringify(params),
    });
    const res = await rsp.json();
    console.log('setSubRoot res', res);
    return res.data;
  } catch (error) {
    console.error('setSubRoot', error);
  }
};
export const getSubRoot = async (params: any): Promise<boolean> => {
  try {
    const rsp = await fetch('https://cri-test.zplan.qq.com/mini_app/get_sub_root', {
      method: 'POST',
      headers,
      body: JSON.stringify(params),
    });
    const res = await rsp.json();
    console.log('getSubRoot res', res);
    return res.data;
  } catch (error) {
    console.error('getSubRoot', error);
    return false;
  }
};
